def render_main_navigation(active_override=None):
    """Fixed icon-only Home / Menu / Scan navigation.

    The three Streamlit buttons are rendered normally, then positioned
    absolutely inside the fixed bottom bar with CSS. This avoids all mobile
    stacking/stretching behaviour from st.columns or horizontal containers.
    """
    nav_options = ["Home", "Menu", "Scan"]
    nav_keys = ["nav_home", "nav_menu", "nav_scan"]

    pending = st.session_state.pop("pending_main_section", None)
    if pending in nav_options:
        st.session_state.main_section = pending

    current = st.session_state.get("main_section", "Home")
    if current not in nav_options:
        current = "Home"
        st.session_state.main_section = current

    visible_active = active_override if active_override in nav_options else current

    def _handle_nav_click(label):
        if active_override == "Scan" and label == "Scan":
            reset(open_scan=True)
        else:
            st.session_state.main_section = label
            st.session_state.stage = "main"
        request_scroll_top()
        st.rerun()

    with st.container(key="gulf_bottom_nav"):
        for label, key in zip(nav_options, nav_keys):
            if st.button(
                label,
                key=key,
                type="primary" if visible_active == label else "secondary",
                use_container_width=False,
            ):
                _handle_nav_click(label)

    return visible_active


def render_segmented_stepper(current_stage: str, triggered: bool):
    raw_steps = [("upload", "Scan")]
    if triggered:
        raw_steps.append(("confirm_dish", "Verify"))
    raw_steps.append(("select_portion", "Portion"))
    raw_steps.append(("result", "Macros"))

    keys = [key for key, _ in raw_steps]
    active_idx = keys.index(current_stage) if current_stage in keys else 0

    segments = []
    labels = []
    for i, (_, label) in enumerate(raw_steps):
        if i < active_idx:
            bg = "#F2D79D"
            shadow = ""
            label_text = f"✓ {label}"
            color = "#B8862E"
            weight = "700"
        elif i == active_idx:
            bg = "linear-gradient(90deg,#F3C36A,#E5A93B)"
            shadow = "box-shadow:0 2px 8px rgba(229,169,59,.24);"
            label_text = f"{i+1}. {label}"
            color = "#1E1B16"
            weight = "900"
        else:
            bg = "#EAE4D8"
            shadow = ""
            label_text = f"{i+1}. {label}"
            color = "#9A9286"
            weight = "650"

        segments.append(
            f'<div style="flex:1;height:5px;border-radius:999px;background:{bg};{shadow}"></div>'
        )
        labels.append(
            f"<span style=\"font-family:'Outfit',sans-serif;font-size:.70rem;font-weight:{weight};color:{color};\">{label_text}</span>"
        )

    st.markdown(
        '<div style="margin:.15rem 0 .9rem 0;">'
        '<div style="display:flex;gap:6px;margin-bottom:7px;">' + ''.join(segments) + '</div>'
        '<div style="display:flex;justify-content:space-between;padding:0 1px;">' + ''.join(labels) + '</div>'
        '</div>',
        unsafe_allow_html=True,
    )


def request_scroll_top():
    """Ask the next rendered screen to reset to its own top anchor."""
    st.session_state["_scroll_top_next"] = True


def render_scroll_anchor():
    """Invisible anchor placed at the top of every navigable app screen."""
    st.markdown(
        '<div data-gulf-scroll-anchor="screen-top" '
        'style="height:0;width:0;overflow:hidden;margin:0;padding:0;"></div>',
        unsafe_allow_html=True,
    )


def apply_pending_scroll_top():
    """Scroll the completed screen to the top after its DOM has rendered."""
    if not st.session_state.pop("_scroll_top_next", False):
        return

    components.html(
        """
        <script>
        (function () {
            const p = window.parent;
            const d = p.document;

            try {
                if ('scrollRestoration' in p.history) {
                    p.history.scrollRestoration = 'manual';
                }
            } catch (e) {}

            function goTop() {
                try {
                    if (d.activeElement && typeof d.activeElement.blur === 'function') {
                        d.activeElement.blur();
                    }
                } catch (e) {}

                const anchor = d.querySelector('[data-gulf-scroll-anchor="screen-top"]');

                if (anchor) {
                    try {
                        anchor.scrollIntoView({
                            behavior: 'instant',
                            block: 'start',
                            inline: 'nearest'
                        });
                    } catch (e) {
                        try { anchor.scrollIntoView(true); } catch (_) {}
                    }
                }

                /* Fallbacks for browsers/Streamlit versions that retain a
                   previous scroll position after widget-triggered reruns. */
                const targets = [
                    d.scrollingElement,
                    d.documentElement,
                    d.body,
                    d.querySelector('[data-testid="stMain"]'),
                    d.querySelector('[data-testid="stAppViewContainer"]'),
                    d.querySelector('section.main')
                ];

                targets.forEach(function (el) {
                    if (!el) return;
                    try { el.scrollTop = 0; } catch (e) {}
                });

                try { p.scrollTo(0, 0); } catch (e) {}
            }

            requestAnimationFrame(goTop);
            [40, 120, 260, 520, 900].forEach(function (ms) {
                setTimeout(goTop, ms);
            });
        })();
        </script>
        """,
        height=0,
        width=0,
    )


def render_workflow_image(image, caption: str, variant: str):
    if image is None:
        return

    if isinstance(image, np.ndarray):
        img = Image.fromarray(image)
    elif isinstance(image, Image.Image):
        img = image.copy()
    else:
        img = Image.open(image).copy()

    if img.mode not in ("RGB", "L"):
        img = img.convert("RGB")

    buf = io.BytesIO()
    img.save(buf, format="JPEG", quality=86, optimize=True)
    uri = "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode("ascii")

    st.markdown(
        f"""
        <div class="workflow-image-card {variant}">
            <img src="{uri}" alt="{caption}">
            <div class="workflow-image-caption">{caption}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )



